package com.sesc.unistudycircle.topic_service.services;
import com.sesc.unistudycircle.topic_service.entities.*; import com.sesc.unistudycircle.topic_service.repositories.TopicRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.List;
@Service @RequiredArgsConstructor public class TopicServiceImpl implements TopicService { private final TopicRepository repository;
 public List<Topic> findAll(){return repository.findAll();} public List<Topic> findPublic(){return repository.findAllByVisibility(TopicVisibility.PUBLIC);} public List<Topic> findMine(String owner){return repository.findAllByOwnerUsername(owner);}
 public Topic view(Long id,Authentication a){Topic t=get(id);if(t.getVisibility()==TopicVisibility.PUBLIC||owns(t,a)||admin(a))return t;throw new AccessDeniedException("This topic is private");}
 public Topic create(Topic t,String owner){t.setTopicId(null);t.setOwnerUsername(owner);t.setStudentName(owner);if(t.getVisibility()==null)t.setVisibility(TopicVisibility.PRIVATE);return repository.save(t);}
 public Topic update(Long id,Topic in,Authentication a){Topic t=get(id);guard(t,a);t.setTopicName(in.getTopicName());t.setTopicDate(in.getTopicDate());t.setTopicContent(in.getTopicContent());if(in.getVisibility()!=null)t.setVisibility(in.getVisibility());return repository.save(t);}
 public void delete(Long id,Authentication a){Topic t=get(id);guard(t,a);repository.delete(t);} private Topic get(Long id){return repository.findById(id).orElseThrow(()->new IllegalArgumentException("Topic not found"));} private boolean owns(Topic t,Authentication a){return a!=null&&a.getName().equals(t.getOwnerUsername());} private boolean admin(Authentication a){return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));} private void guard(Topic t,Authentication a){if(!owns(t,a)&&!admin(a))throw new AccessDeniedException("You can only modify your own topics");}}
